Gtk::Widget* CustomPrintOperation::on_create_custom_widget()
{
  set_custom_tab_label("My custom tab");

  auto hbox = new Gtk::Box(Gtk::Orientation::HORIZONTAL, 8);
  hbox->set_margin(6);

  auto label = Gtk::make_managed<Gtk::Label>("Enter some text: ");
  hbox->append(*label);

  hbox->append(m_Entry);

  return hbox;
}

